mapper.select:
SELECT tm.disabled AS tabFlag, count(1) AS count FROM template_management as tm WHERE tm.is_deleted=FALSE
${params.permissionSql}
GROUP BY tm.disabled

mapper.sql:
SELECT tm.ID AS ID, tm.create_user_id AS createUserId, tm.create_user_name AS createUserName, tm.create_time AS createTime, tm.update_user_id AS updateUserId, tm.update_user_name AS updateUserName, tm.update_time AS updateTime, tm.VERSION AS VERSION, tm.is_deleted AS isDeleted, tm.disabled AS disabled, tm.code AS code, tm.NAME AS NAME, tm.TYPE AS TYPE, tm.biz_type AS bizType, tm.status AS status, tm.LENGTH AS LENGTH, tm.width AS width, tm.CONTENT AS CONTENT, tm.template_version AS templateVersion, tm.is_default AS isDefault, tm.INDEX AS INDEX FROM template_management AS tm WHERE ${params.sqlMap.default} AND tm.is_deleted = FALSE
and tm.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
tm.create_time DESC
